namespace sv_a43f5065a47e4330bc0aa7079f908c75.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public IReadOnlyList<Warehouse> Warehouses { get; } = new List<Warehouse>
    {
        new("WH-001", "Warehouse A - Downtown"),
        new("WH-002", "Warehouse B - Airport"),
        new("WH-003", "Warehouse C - Industrial Park"),
        new("WH-004", "Warehouse D - Harbor District")
    };

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record Warehouse(string Id, string Name);

namespace sv_a43f5065a47e4330bc0aa7079f908c75.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private Timer? _pollingTimer;
    private int _subscriberCount;
    private int _currentLowStockCount;
    private readonly Random _random = new();
    private readonly object _lock = new();

    public int CurrentLowStockCount => _currentLowStockCount;

    public event Func<Task>? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component subscribes to alerts. Starts polling when first subscriber joins.
    /// </summary>
    public void Subscribe()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                StartPolling();
            }
        }
    }

    /// <summary>
    /// Call when a component unsubscribes. Stops polling when last subscriber leaves.
    /// </summary>
    public void Unsubscribe()
    {
        lock (_lock)
        {
            _subscriberCount--;
            if (_subscriberCount <= 0)
            {
                _subscriberCount = 0;
                StopPolling();
            }
        }
    }

    private void StartPolling()
    {
        _pollingTimer?.Dispose();
        _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    private void StopPolling()
    {
        _pollingTimer?.Dispose();
        _pollingTimer = null;
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        _currentLowStockCount = count;
        await NotifySubscribers();
    }

    private async void HandleWarehouseChanged()
    {
        // Immediately re-poll when warehouse changes
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        _currentLowStockCount = count;
        await NotifySubscribers();
    }

    private async Task NotifySubscribers()
    {
        if (OnAlertDataChanged is not null)
        {
            await OnAlertDataChanged.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _pollingTimer?.Dispose();
    }
}

