@rendermode InteractiveServer
@using sv_a43f5065a47e4330bc0aa7079f908c75.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select"><strong>Current Warehouse:</strong></label>
    <select id="warehouse-select" class="form-select form-select-sm" 
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@using sv_a43f5065a47e4330bc0aa7079f908c75.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge" title="Low stock items">
    @if (AlertService.CurrentLowStockCount > 0)
    {
        <span class="badge bg-danger">@AlertService.CurrentLowStockCount</span>
    }
    else
    {
        <span class="badge bg-success">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        AlertService.Subscribe();
    }

    private async Task HandleAlertDataChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        AlertService.Unsubscribe();
    }
}

