        <p>
            Low Stock Alerts:
            @if (_lowStockCount > 0)
            {
                <span class="badge bg-danger fs-6">@_lowStockCount items below minimum</span>
            }
            else
            {
                <span class="badge bg-success fs-6">All stock levels OK</span>
            }
        </p>
        <p class="text-muted"><small>Auto-refreshes every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</small></p>
    </div>
</div>

<div class="card">
    <div class="card-header">
        <h5>📊 Inventory Status Summary</h5>
    </div>
