                </tr>
                <tr>
                    <td>Low Stock Alerts</td>
                    <td>@_lowStockCount</td>
                </tr>
                <tr>
                    <td>Polling Status</td>
                    <td><span class="badge bg-info">Active</span></td>
                </tr>
            </tbody>
        </table>
    </div>
</div>

@code {
    private int _lowStockCount;
    private DateTime _lastUpdate = DateTime.Now;

    protected override void OnInitialized()
    {
        _lowStockCount = AlertService.CurrentLowStockCount;
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        AlertService.Subscribe();
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

